mod = 1000000007

def count_trees(n, d):
    if d == 2:
        if n % 2 == 0:
            return 1
        else:
            return 0
    dp = [0] * (d + 1)
    dp.append(1) # Base case

    for i in range(2, d + 1):
        for j in range(i, d + 1):
            dp[j] = ((dp[j] + dp[i - 1] * (d + 1 - (i - j) * 2) % mod) % mod + mod) % mod

    return dp[n % (d + 1)]

