def lcp(X):
    """
    Longest common prefix length of BN-string X
    """
    arr = []
    for x in X:
        if arr and arr[-1] > x:
            idx = len(arr) - 1
            while arr[idx] > x and arr[idx - 1] <= x:
                if idx == 0:
                    break
                arr.pop(idx - 1)
                if x <= arr[-1]:
                    arr.append(x)
                    break
                if x > arr[-1] or idx == 0:
                    arr.append(x)
                    break
                if len(arr) >= 2:
                    arr.append(max([arr[idx - 1], arr[idx]]))
                else:
                    arr.append(x)
                break
            if idx == 0:
                outer = 0
            else:
                idx -= 1

            while idx >= 0:
                if arr[idx] > x:
                    unas = arr.pop(idx), arr.pop(idx - 1)
                else:
                    unas = arr.pop(), arr.pop()
                arr.insert(idx, max(new_a[0] for new_a in unas))
                idx += -1

            if not arr or x > arr[-1]:
                arr.append(x)

        arr.append(x)
    return len(X) - len(arr) if arr else -len(X)

