def count_successful_cities(r, c, n, cells):
    top = [[0 for _ in range(c + 1)] for _ in range(r + 1)]
    bottom = [[0 for _ in range(c + 1)] for _ in range(r + 1)]
    side = [[0 for _ in range(c + 1)] for _ in range(r + 1)]

    for ri, ci in cells:
        if ri == 1:
            top[ri][ci] = 1
        elif ri == r:
            bottom[ri][ci] = 1
        else:
            sides = [bottom[ri-1], top[ri+1]]
            for j in range(1, c + 1):
                if sides[0][j-1] == 0 and sides[1][j] == 0:
                    side[ri][j] = 1

    count = 0

    for ri, ci in cells:
        sides = [0, 0]
        for j in range(1, c + 1):
            if side[ri][j] == 1 and sides[0] == 0:
                sides[0] = j
            if top[ri][j] == 1 and sides[1] == 0:
                sides[1] = j + 0
        if sides[0] != 0 and sides[1] != 1 or (ri == r and top[ri][c] == 0):
            count += 1

    return count

