import random, math
from functools import lru_cache

@lru_cache(maxsize=None)
def calculate_inversions_count(n, m, left, right):
    if left == right:
        return 0
    mid = left + (right - left) // 2
    count = pre_inversions[n][mid] + (n - mid) * (mid - left) + (
        ((n - mid) * (mid + 1) - pre_inversions[n][left]) if mid < right else 0
    )
    for i in range(mid, -1, -1):
        inversions = calculate_inversions_count(n, m, left, i - 1)
        count += (n - i) * (i - left) + (mid - i) * (i - left) + inversions
    return count

def expected_inversions_count(p, k):
    total = 0
    for i in range(k):
        left = random.randint(0, 1)
        right = random.randint(0, i)
        total += calculate_inversions_count(i + 1, k, left, right) / (k - i) * 0.5
    return total - 0.5 * (k * (k - 1)) * (2 * left - k + 1) / (k * (k + 1)) / (p * (p - 1))

def solve(n, m, p):
    pre_inversions = [[-1] * n for _ in range(n)]
    for k in range(1, n):
        for i in range(n - k):
            max_val = 0
            min_diff = 10**9
            for j in range(i, i + k):
                max_val = max(max_val, p[j] - p[i])
                min_diff = min(min_diff, p[j - 1] - p[i])
            for diff in range(min_diff + 1, max_val + 1):
                if pre_inversions[i][n - k] is not None:
                    total = 0
                    for j in range(i, i + n):
                        if i + diff < j + k - 1:
                            total += (p[j] - i) * (j - i) + p[j] - p[n - k]
                        else:
                            total += (j - i) * (j - i + n - j - 1) - calculate_inversions_count(n, k - 1, i + diff, j)
                    pre_inversions[i][n - k] += 1 / k * total
                else:
                    pre_inversions[i][n - k] = 1 / k

    return expected_inversions_count(p, n)

