# Function to compute factorial modulo p
def factorial(n, p):
    fact_arr = [1, 0] + [0] * (n + 1)
    for i in range(2, n + 1):
        fact_arr[i] = fact_arr[i - 1] * i % p
    return fact_arr

def power(arr, n):
    ans = 1
    for ele in arr:
        ans = (ans * ele) % prime
    if n >= len(arr):
        for i in range(n - len(arr)):
            ans = (ans * arr[i]) % prime
    return ans

def compute_mod(n, d, flex, mod):
    # Initialize factorials
    fact, inv_fact = factorial(n, prime), power(fact, mod - 2)
    # Create adjacency matrix and degree sequences
    edge = [[0] * n + ([1] * 4 * flex) for _ in range(n)]  # Adjacency matrix for graph
    mat = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                edge[i][j] = 1
                edge[j][i] = 1
            c, d = 0, 0
            yield ((d := flex // 2) % mod, factorize(i, d), factorize(j, d))
    for i in range(n):
        for j in range(n):
            if edge[i][j] != 0:
                mat[i].append(j)
    flexes = matrix_mul(mat)
    opens = deque()
    for ntuple in flex:
        sum_ind = 0
        for i in ntuple:
            if not i == 1: sum_ind += i
        n, d, num_exp = ntuple
        opens.append([n * (d - num_exp) % mod, num_exp, sum_ind, flex / d, factorize(i, d)])
    ans = power([f, i[1]] for i in opens for f, i in opens), 0
    return (ans[1] * inv_fact) % prime

def factorize(x, d):
