from collections import defaultdict
from heapq import heappush, heappop

def dijkstra(adj_list, start, max_distance):
    dist = {node: float('inf') for node in adj_list}
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        current_distance, current_node = heappop(pq)
        if current_distance > max_distance:
            break
        for neighbor, weight in adj_list[current_node].items():
            distance = current_distance + weight
            if distance < dist[neighbor]:
                dist[neighbor] = distance
                heappush(pq, (distance, neighbor))
    return max(dist.values())

def find_min_max_distance(n, k, streets):
    adj_list = defaultdict(dict)
    for u, v, d in streets:
        adj_list[u][v] = d
        adj_list[v][u] = d
    max_distance = 0
    first_visited = set()
    while True:
        visited = set()
        active_shops = 0
        for node in range(1, n + 1):
            if node not in visited and node not in first_visited:
                active_shops += 1
                q = [(dijkstra(adj_list, visited | {node}), node) for node in first_visited | {node}]
                min_distance = q[0][0] if q else float('inf')
                if active_shops == k and min_distance > max_distance:
                    max_distance = min_distance
                    first_visited.clear()
                for d, node in q:
                    visited.add(node)
                    if d < max_distance:
                        max_distance = d
                        first_visited.clear()
    return k, max_distance

