from functools import lru_cache

def min_swaps_to_remove_vk(s):
    n = len(s)

    @lru_cache(maxsize=None)
    def dp(i, has_vk):
        if i == n:
            return 0
        if s[i] == 'V':
            return min(dp(i+1, False), 1 + dp(i+1, True))
        if s[i] == 'K':
            return min(dp(i+1, has_vk), dp(i+1, not has_vk) + 1)
        return 0

    return dp(0, False)

