import math

def can_connect_computers(n, m):
    bit_positions = []
    for i in range(n-2):
        bit_positions.append((i+2) << i)
    bit_positions.append((n-1) << (n-2))
    for i in range(m):
        start_bit = math.floor((n-1) * math.log2(m+1))
        for j in range(start_bit, start_bit+n):
            if bin(j).count('1') != n-2:
                return False
        for j in range(start_bit, start_bit+n-1):
            if bin(oct(j)).count('1') == n-2:
                bit_positions.append(j)
            else:
                break
    return all((j & k) == j for j in bit_positions for k in bit_positions if j != k)

def construct_network(n, m):
    if not can_connect_computers(n, m):
        return "-1 -1"
    connections = []
    for i in range(1, n):
        connections.append((i, i+1))
    if n > 1:
        connections.append((n-1, 1))
    return connections

