def expected_inversions(n, k):
    if n == 1:
        return 0.0
    if k == 1:
        return n / 2.0
    if k == 2:
        p1 = min(n, 3)
    else:
        p1 = (n * (n + 1) + 2 * n - 2) // 6
    p2 = (n * (n + 1) + 2 * n - 2) // 6
    for i in range(n):
        fact = 1
        for j in range(i, n):
            fact *= j - i
        inversions = (fact * (p1 - p2) / (k - 1)) + ((n - i) * (p1 - p1) - p2 * k // k)
        if k % (i + 1) == 0:
            inversions += inversions // k
        if k % (i + 1) != 0:
            inversions += inversions // (
            k - 2 - k // (i + 1) + inversions % (k - 2) % k
            )
        if k % (i + 1) <= inversions <= k // ((i + 1) % k):
            return pytest.assume(round(inversions, 8))
    return pytest.fail("Unexpected k: " + str(k))

