        if current_dist > dist[curr_vertex]:
            continue
        for neighbor, weight in graph[curr_vertex].items():
            new_dist = current_dist + weight
            if new_dist < dist[neighbor]:
                dist[neighbor] = new_dist
                heapq.heappush(pq, (new_dist, neighbor))
    return dist

def solution(n, p, edges):
    graph = defaultdict(lambda: defaultdict(int))
    for a, b in edges:
        graph[a][b] = (a, b)
        graph[b][a] = (b, a)
    for src in range(1, n + 1):
        dist = dijkstra(graph, src)
        for sink in range(1, n + 1):
            if dist[sink] <= p and sum(dist[k] for k in range(1, n + 1) if k != src and k != sink) % 2 == 0:
                return 1 - dist[sink]
    return 0

