from collections import Counter

def calculate_cost(segment):
    cost = 0
    if len(segment) > 1:
        first_occurrence = None
        last_occurrence = None
        for index, value in enumerate(segment):
            if value == first_occurrence and first_occurrence is not None:
                for i in range(index-1, -1, -1):
                    if segment[i] != value:
                        first_occurrence = None
                        break
                    prev_index = i + 1
                if first_occurrence is not None:
                    first_occurrence = prev_index
            if value == last_occurrence:
                for i in range(index+1, len(segment)):
                    if segment[i] != value:
                        last_occurrence = None
                        break
                    next_index = i - 1
                if last_occurrence is not None:
                    last_occurrence = next_index
            if first_occurrence is not None and last_occurrence is not None:
                cost += (last_occurrence + 1) - (first_occurrence - 1)
    return cost

def minimum_segment_cost(arr, k):
    segment_indices = [(i, i + k) for i in range(len(arr) - 2*k + 1)]
    segment_weights = [0]*len(segment_indices)
    cost_counter = Counter()
    for i in range(len(arr)):
        first_occurrence = segment_indices[i][0]
        last_occurrence = segment_indices[i+1][1]
        new_cost_counter = Counter(cost_counter)
        cost_counter = Counter({last_occurrence[j]: val for j, val in new_cost_counter.items() if j - first_occurrence not in cost_counter})
        segment_weights[i] = cost_counter.max()[1]
    return sum(max(n - m, 0) for m, n in segment_weights)

