def min_swaps_to_remove_vk(n, s):
    """
    Calculate the minimum number of adjacent swaps required to remove any occurrence of 'VK' substring from the string s.
    """
    if 'VK' in s:
        return n

    sequences = set()

    for i in range(n):
        sequences.add(s[i:])
        sequences.add(s[:i] + s[i+1:])

    for sequence in sequences:
        swap_points = [(i, chr(ord('K')) + sequence[i]) for i, char in enumerate(sequence) if char == 'V']

        for start1, end1 in swap_points:
            for start2, end2 in swap_points:
                if end1 == end2:
                    continue
                if start2 + len(start1) == end1 == end2:
                    swap = [(start1[1:i + len(start1) - 1], "*", end1[1:i + len(sequence[i + 1 - end1]) - 1]) + end1[i + len(sequence[i + 1 - end1]):] + [sequence[start2 + len(start1) - 1]]
                    swapped = phrase = ""
                    for char in sequence:
                        if char != "*":
                            frame = ""
                            for swap_char in swap:
                                frame = frame + ("*" if char == swap_char[0] else swap_char[1])
                            frame += char
                            if frame != char:
                                frame += char
                            if frame != char:
                                frame += char
                            if frame != char:
                                frame += char
                            if frame != char:
                                frame += char
                            if frame != char:
                                frame += char
                            if frame != char:
                                frame += frame
                            swap += [i for x in frame.replace(char, "**").split("*") for i, char in enumerate(x) if char != "*"]
                            phrase = phrase + char
                            shortest_swaps = min(len(x) - 1 for x in swap if i in x)
                        else:
                            i += 1
                            phrase += char
                    return shortest_swaps
    return 0

