def implies(triples):
    return len(triples) == 1 + sum(len(triple) for triple in triples)

def solution(N, M):
    if N < 3 or M < 3*N-3 or N*(N-1)//2 < 3*(N-1)-2:
        return -1, -1

    pairs = set()
    for _ in range(M//3):
        i, j, k = input().split()
        k -= 1
        pairs.add((int(i), int(j)))
        pairs.add((int(j), int(k)))
        pairs.add((int(i), int(k)))

    return lists_to_pairs(range(1, N+1)), [*pairs]

def lists_to_pairs(lst):
    triplets = []
    for a, b in lst:
        c = lst[:a] + [(a, b)] + lst[a+1:]
        if implies(c):
            triplets.append(c)
    return triplets

def validate(N, M, pairs, potential_netwrok):
    K_minus_1 = int((N * (N - 1)) / 2)
    if K_minus_1 != M + len(potential_netwrok) or (N-1 > 2 and M + len(potential_netwrok) != sum(len(triple) for triple in potential_netwrok)):
        return False
    if any(len(triplets) == 1 for triplets in [triples for triplets in potential_netwrok if triples]):
        return False
    return True

