def rand_pivot(n, k):
    a = rand_arr(n).copy()
    a = np.sort(a)
    return a[-1::-1][:k]

def rand_bin(n, k):
    a = rand_arr(n).copy()
    a = rand_bin_arr(a, k)
    return a[:,::-1][:k]

def rand_arr(n):
    A = np.random.permutation(n)
    A[0::2], A[1::2] = np.random.permutation(n)
    return A

def rand_bin_arr(x, k):
    for _ in range(k):
        rr = np.random.randint(x.size)
        rr1 = np.random.binomial(1, x[rr:] != x[rr-1])
        idx = np.random.choice(np.nonzero(rr1 == 1)[0] + 1)
        x[rr + idx:] -= 1
    return x

def expected_value(n, k):
