from collections import defaultdict, deque

def visit_leaves(n, k, parents):
    graph = defaultdict(list)
    for i in range(2, n + 1):
        graph[parents[i - 2]].append(i)

    leaves = [1]
    visited = set([1])

    level = 0
    while level < n:
        for i in range(len(leaves)):
            leaf = leaves[i]
            for child in graph[leaf]:
                if child not in visited:
                    visited.add(child)
                    leaves.append(child)
        level += 1
        while len(leaves) - 1 < n:
            visited.remove(leaves.pop(0))

    return len(visited)

# Input
n, k = map(int, input().split())
parents = list(map(int, input().split()))

print(visit_leaves(n, k, parents))
